// TodoMVC app
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var STORAGE_KEY = 'todos-javascript';

  /* ------------------------------------------------------------------ */
  /*  Persistence                                                       */
  /* ------------------------------------------------------------------ */

  function loadTodos() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        var parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          todoList = parsed;
          // Recover the highest id
          for (var i = 0; i < todoList.length; i++) {
            if (todoList[i].id > idCounter) idCounter = todoList[i].id;
          }
          return;
        }
      }
    } catch (e) { /* ignore */ }
    todoList = [];
  }

  function loadFilter() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY + '_filter');
      if (stored) return stored;
    } catch (e) { /* ignore */ }
    return '';
  }

  function saveFilter(f) {
    localStorage.setItem(STORAGE_KEY + '_filter', f);
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todoList));
  }

  function saveFilter(filter) {
    try {
      if (filter === 'all') {
        localStorage.removeItem(STORAGE_KEY + '_filter');
      } else {
        localStorage.setItem(STORAGE_KEY + '_filter', filter);
      }
    } catch (e) { /* ignore */ }
  }

  var todoList = [];
  var idCounter = 0;
  var currentFilter = 'all';
  loadTodos();

  /* ------------------------------------------------------------------ */
  /*  Routing                                                           */
  /* ------------------------------------------------------------------ */

  function getFilterFromHash() {
    var hash = window.location.hash || '';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function restoreFilter() {
    var saved = loadFilter();
    if (saved && saved !== 'all') {
      currentFilter = saved;
      if (saved === 'active') window.location.hash = '#/active';
      else if (saved === 'completed') window.location.hash = '#/completed';
    } else {
      currentFilter = getFilterFromHash();
    }
  }

  function filterTodos(list, filter) {
    if (filter === 'active') {
      return list.filter(function (t) { return !t.completed; });
    }
    if (filter === 'completed') {
      return list.filter(function (t) { return t.completed; });
    }
    return list;
  }

  /* ------------------------------------------------------------------ */
  /*  DOM refs                                                           */
  /* ------------------------------------------------------------------ */

  var newTodoInput = document.querySelector('.new-todo');
  var todoListEl = document.querySelector('.todo-list');
  var mainEl = document.querySelector('.main');
  var footerEl = document.querySelector('.footer');
  var todoCountEl = document.querySelector('.todo-count');

  /* ------------------------------------------------------------------ */
  /*  Render                                                             */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("the main section is hidden")
   * @planks("the main section is visible")
   * @planks("the footer is hidden")
   * @planks("the footer is visible")
   * @planks("the todo list is empty")
   * @planks("the todo list contains {int} item")
   * @planks("the todo list contains {int} items")
   * @planks("the new item has title {string}")
   * @planks("the new item is not completed")
   * @planks("the new-todo input is cleared")
   * @planks("the todo-count reads {string}")
   * @planks("the clear-completed button is hidden")
   * @planks("the clear-completed button is visible")
   * @planks("I navigate to {string}")
   * @planks("the {string} route is active")
   * @planks("the All filter link has the {string} class")
   * @planks("the Active filter link has the {string} class")
   * @planks("the Completed filter link has the {string} class")
   * @planks("the visible items include {string}")
   * @planks("the visible items do not include {string}")
   */
  function render() {
    var filteredList = filterTodos(todoList, currentFilter);

    // Clear the list and rebuild using DOM methods
    while (todoListEl.firstChild) {
      todoListEl.removeChild(todoListEl.firstChild);
    }
    for (var i = 0; i < filteredList.length; i++) {
      var t = filteredList[i];
      var li = document.createElement('li');
      if (t.completed) li.className = 'completed';
      li.setAttribute('data-id', t.id);

      var view = document.createElement('div');
      view.className = 'view';

      var toggle = document.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      if (t.completed) toggle.checked = true;
      view.appendChild(toggle);

      var label = document.createElement('label');
      label.textContent = t.title;
      view.appendChild(label);

      var destroy = document.createElement('button');
      destroy.className = 'destroy';
      view.appendChild(destroy);

      li.appendChild(view);

      var edit = document.createElement('input');
      edit.className = 'edit';
      edit.value = t.title;
      li.appendChild(edit);

      todoListEl.appendChild(li);
    }

    var activeCount = 0;
    for (var j = 0; j < todoList.length; j++) {
      if (!todoList[j].completed) activeCount++;
    }

    var word = activeCount === 1 ? 'item' : 'items';
    // Build the count text with <strong> using DOM methods
    while (todoCountEl.firstChild) {
      todoCountEl.removeChild(todoCountEl.firstChild);
    }
    var strong = document.createElement('strong');
    strong.textContent = String(activeCount);
    todoCountEl.appendChild(strong);
    todoCountEl.appendChild(document.createTextNode(' ' + word + ' left'));

    if (todoList.length === 0) {
      mainEl.style.display = 'none';
      footerEl.style.display = 'none';
    } else {
      mainEl.style.display = 'block';
      footerEl.style.display = 'block';
    }

    var completedCount = todoList.length - activeCount;
    var clearBtn = document.querySelector('.clear-completed');
    if (clearBtn) {
      if (completedCount === 0) {
        clearBtn.style.display = 'none';
      } else {
        clearBtn.style.display = 'block';
      }
    }

    saveTodos();

    // Update filter link selected class
    var links = document.querySelectorAll('.filters a');
    for (var l = 0; l < links.length; l++) {
      links[l].classList.remove('selected');
      var href = links[l].getAttribute('href');
      if ((currentFilter === 'all' && (href === '#/' || href === '#' || href === '')) ||
          (currentFilter === 'active' && href === '#/active') ||
          (currentFilter === 'completed' && href === '#/completed')) {
        links[l].classList.add('selected');
      }
    }
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  }

  /* ------------------------------------------------------------------ */
  /*  New todo                                                           */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I type {string} into the new-todo input and press Enter")
   */
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var title = newTodoInput.value.trim();
    if (title === '') return;
    todoList.push({ id: ++idCounter, title: title, completed: false });
    newTodoInput.value = '';
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Toggle completion                                                  */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I toggle the {string} todo")
   * @planks("the {string} todo is marked completed")
   * @planks("the {string} todo is not completed")
   */
  todoListEl.addEventListener('click', function (e) {
    var toggle = e.target.closest('.toggle');
    if (!toggle) return;
    var li = toggle.closest('li');
    if (!li) return;
    var id = parseInt(li.getAttribute('data-id'), 10);
    for (var i = 0; i < todoList.length; i++) {
      if (todoList[i].id === id) {
        todoList[i].completed = !todoList[i].completed;
        break;
      }
    }
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Toggle all                                                        */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I toggle the mark-all-complete checkbox")
   * @planks("every todo is marked completed")
   * @planks("the mark-all-complete checkbox is checked")
   * @planks("the mark-all-complete checkbox is not checked")
   */
  document.querySelector('.toggle-all').addEventListener('change', function () {
    var allCompleted = true;
    for (var i = 0; i < todoList.length; i++) {
      if (!todoList[i].completed) { allCompleted = false; break; }
    }
    var newState = !allCompleted;
    for (var j = 0; j < todoList.length; j++) {
      todoList[j].completed = newState;
    }
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Destroy (event delegation)                                        */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I click the destroy button for {string}")
   * @planks("the todo list does not contain {string}")
   */
  todoListEl.addEventListener('click', function (e) {
    var btn = e.target.closest('.destroy');
    if (!btn) return;
    var li = btn.closest('li');
    if (!li) return;
    var id = parseInt(li.getAttribute('data-id'), 10);
    for (var i = 0; i < todoList.length; i++) {
      if (todoList[i].id === id) {
        todoList.splice(i, 1);
        break;
      }
    }
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Clear completed                                                   */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I click the clear-completed button")
   */
  document.querySelector('.clear-completed').addEventListener('click', function () {
    todoList = todoList.filter(function (t) { return !t.completed; });
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Edit mode                                                         */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I double-click the label of {string}")
   * @planks("the {string} todo is in editing mode")
   * @planks("the edit input is focused")
   * @planks("the edit input value is {string}")
   * @planks("the toggle checkbox is hidden")
   * @planks("the destroy button is hidden")
   * @planks("I type {string} into the edit input and press Enter")
   * @planks("I type {string} into the edit input and blur")
   * @planks("I type {string} into the edit input and press Escape")
   * @planks("the {string} todo is not in editing mode")
   * @planks("the {string} todo exists")
   * @planks("the {string} todo does not exist")
   * @planks("the todo item title is {string}")
   */
  todoListEl.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    li.classList.add('editing');
    // Hide the view, show the edit input (CSS would do this, but happy-dom doesn't apply CSS)
    var view = li.querySelector('.view');
    if (view) view.style.display = 'none';
    var editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.style.display = 'block';
      editInput.value = li.querySelector('label').textContent;
      editInput.focus();
    }
  });

  todoListEl.addEventListener('keydown', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;

    if (e.keyCode === ENTER_KEY) {
      saveEdit(li, editInput);
    } else if (e.keyCode === 27) {
      cancelEdit(li);
    }
  });

  todoListEl.addEventListener('blur', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    saveEdit(li, editInput);
  }, true);

  function cancelEdit(li) {
    li.classList.remove('editing');
    var view = li.querySelector('.view');
    if (view) view.style.display = '';
    var editInput = li.querySelector('.edit');
    if (editInput) editInput.style.display = '';
  }

  function saveEdit(li, editInput) {
    var title = editInput.value.trim();
    var id = parseInt(li.getAttribute('data-id'), 10);
    if (title === '') {
      for (var i = 0; i < todoList.length; i++) {
        if (todoList[i].id === id) {
          todoList.splice(i, 1);
          break;
        }
      }
    } else {
      for (var j = 0; j < todoList.length; j++) {
        if (todoList[j].id === id) {
          todoList[j].title = title;
          break;
        }
      }
    }
    render();
  }

  /* ------------------------------------------------------------------ */
  /*  Initial render                                                     */
  /* ------------------------------------------------------------------ */

  currentFilter = 'all';

  window.addEventListener('hashchange', function () {
    currentFilter = getFilterFromHash();
    saveFilter(currentFilter);
    render();
  });

  restoreFilter();
  // Ensure the hash reflects currentFilter
  if (!window.location.hash || window.location.hash === '') {
    if (currentFilter === 'all') {
      window.location.hash = '#/';
    } else if (currentFilter === 'active') {
      window.location.hash = '#/active';
    } else if (currentFilter === 'completed') {
      window.location.hash = '#/completed';
    }
  }
  render();
}());

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

/* ------------------------------------------------------------------ */
/*  Background / app load                                              */
/* ------------------------------------------------------------------ */

Given('the app is loaded', function () {
  // The Before hook in world.js already loads the app before every scenario.
  // This step is a no-op that anchors the Given clause.
});

/* ------------------------------------------------------------------ */
/*  New-todo input                                                     */
/* ------------------------------------------------------------------ */

When('I type {string} into the new-todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

/* ------------------------------------------------------------------ */
/*  Todo list assertions                                               */
/* ------------------------------------------------------------------ */

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to be empty');
});

Then('the todo list contains {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} items, found ${items.length}`);
});

Then('the todo list contains {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} items, found ${items.length}`);
});

Then('the new item has title {string}', function (expectedTitle) {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  assert.ok(lastItem, 'No todo items found');
  const label = lastItem.querySelector('label');
  assert.ok(label, 'Last todo item has no label');
  assert.strictEqual(label.textContent.trim(), expectedTitle,
    `Expected title "${expectedTitle}", got "${label.textContent.trim()}"`);
});

Then('the new item is not completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  assert.ok(lastItem, 'No todo items found');
  assert.ok(!lastItem.classList.contains('completed'), 'Expected new item to not be completed');
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  assert.strictEqual(input.value, '', 'Expected new-todo input to be cleared');
});

/* ------------------------------------------------------------------ */
/*  Section visibility                                                 */
/* ------------------------------------------------------------------ */

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Main section not found');
  // happy-dom does not implement getComputedStyle, so check inline style / hidden attribute
  assert.ok(main.style.display === 'none' || main.hidden || main.classList.contains('hidden'),
    'Expected main section to be hidden');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Main section not found');
  assert.ok(main.style.display !== 'none' && !main.hidden && !main.classList.contains('hidden'),
    'Expected main section to be visible');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer not found');
  assert.ok(footer.style.display === 'none' || footer.hidden || footer.classList.contains('hidden'),
    'Expected footer to be hidden');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer not found');
  assert.ok(footer.style.display !== 'none' && !footer.hidden && !footer.classList.contains('hidden'),
    'Expected footer to be visible');
});

/* ------------------------------------------------------------------ */
/*  Todo-count                                                         */
/* ------------------------------------------------------------------ */

Then('the todo-count reads {string}', function (expected) {
  const el = this.document.querySelector('.todo-count');
  assert.ok(el, 'todo-count element not found');
  assert.strictEqual(el.textContent.trim(), expected,
    `Expected todo-count "${expected}", got "${el.textContent.trim()}"`);
});

/* ------------------------------------------------------------------ */
/*  Todos with pre-populated state                                     */
/* ------------------------------------------------------------------ */

Given('the app is loaded with todos:', function (dataTable) {
  // The Before hook already loaded the app. Now populate todos from the table.
  const rows = dataTable.hashes();
  for (let i = 0; i < rows.length; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = rows[i].title;
    input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
      key: 'Enter', keyCode: 13, bubbles: true
    }));
  }
  // Mark completed todos as specified in the table
  for (let i = 0; i < rows.length; i++) {
    if (rows[i].completed === 'true') {
      const items = this.document.querySelectorAll('.todo-list li');
      const toggle = items[i].querySelector('.toggle');
      if (toggle && !toggle.checked) {
        toggle.click();
      }
    }
  }
});

/* ------------------------------------------------------------------ */
/*  Toggle completion                                                  */
/* ------------------------------------------------------------------ */

When('I toggle the {string} todo', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      const toggle = items[i].querySelector('.toggle');
      assert.ok(toggle, `Toggle for "${title}" not found`);
      toggle.click();
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

/* ------------------------------------------------------------------ */
/*  Completion assertions                                              */
/* ------------------------------------------------------------------ */

Then('the {string} todo is marked completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.ok(items[i].classList.contains('completed'),
        `Expected "${title}" to be completed`);
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the {string} todo is not completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.ok(!items[i].classList.contains('completed'),
        `Expected "${title}" to not be completed`);
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});
/* ------------------------------------------------------------------ */
/*  Mark all as complete                                               */
/* ------------------------------------------------------------------ */

When('I toggle the mark-all-complete checkbox', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox not found');
  checkbox.click();
});

Then('every todo is marked completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    assert.ok(items[i].classList.contains('completed'),
      `Expected todo ${i} to be completed`);
  }
});

Then('the mark-all-complete checkbox is checked', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox not found');
  assert.ok(checkbox.checked, 'Expected toggle-all checkbox to be checked');
});

Then('the mark-all-complete checkbox is not checked', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox not found');
  assert.ok(!checkbox.checked, 'Expected toggle-all checkbox to not be checked');
});

/* ------------------------------------------------------------------ */
/*  Clear completed                                                    */
/* ------------------------------------------------------------------ */

When('I click the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'clear-completed button not found');
  btn.click();
});

/* ------------------------------------------------------------------ */
/*  Destroy / hover                                                    */
/* ------------------------------------------------------------------ */

When('I hover over the {string} todo', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      items[i].dispatchEvent(new this.window.Event('mouseover', { bubbles: true }));
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the destroy button for {string} is visible', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      const btn = items[i].querySelector('.destroy');
      assert.ok(btn, `Destroy button for "${title}" not found`);
      assert.ok(btn.style.display !== 'none' && !btn.hidden,
        `Destroy button for "${title}" is not visible`);
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

When('I click the destroy button for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      const btn = items[i].querySelector('.destroy');
      assert.ok(btn, `Destroy button for "${title}" not found`);
      btn.click();
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the todo list does not contain {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.fail(`Todo "${title}" should not be in the list`);
    }
  }
});

/* ------------------------------------------------------------------ */
/*  Editing mode                                                       */
/* ------------------------------------------------------------------ */

When('I double-click the label of {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the {string} todo is in editing mode', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.ok(items[i].classList.contains('editing'),
        `Expected "${title}" todo to be in editing mode`);
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the edit input is focused', function () {
  const active = this.document.activeElement;
  assert.ok(active && active.classList.contains('edit'),
    'Expected edit input to be focused');
});

Then('the edit input value is {string}', function (expected) {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'Edit input not found');
  assert.strictEqual(edit.value, expected,
    `Expected edit value "${expected}", got "${edit.value}"`);
});

Then('the toggle checkbox is hidden', function () {
  const toggle = this.document.querySelector('.todo-list li.editing .toggle');
  assert.ok(toggle, 'Toggle checkbox not found');
  const view = toggle.closest('.view');
  // The toggle may be hidden by parent .view being display:none
  assert.ok(toggle.style.display === 'none' || toggle.hidden || toggle.classList.contains('hidden') ||
    (view && (view.style.display === 'none' || view.hidden)),
    'Expected toggle checkbox to be hidden');
});

